import time, os, random
from cryptography.hazmat.primitives import hashes
import hashlib

def crypto_hash(data):
    d = hashes.Hash(hashes.SHA256())
    d.update(data)
    return d.finalize()

def bench(size):
    data=os.urandom(size)
    t=time.time(); crypto_hash(data); print('crypto', time.time()-t)
    t=time.time(); hashlib.sha256(data).digest(); print('hash', time.time()-t)
for s in [1, 1024, 16384, 1_000_000, 20_000_000]:
    print('size', s)
    bench(s)
